(function(){
 const $=s=>document.querySelector(s),esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const copy=x=>JSON.parse(JSON.stringify(x)),store='pg11-task-record-v3';let data,active='s1',sequence=0;
 const names={success:'处理已完成',running:'正在处理',failed:'处理失败',cancelled:'已取消'};
 const all=()=>data.conversations||[],conv=()=>all().find(x=>x.id===active)||all()[0],attempts=()=>conv().requests.flatMap(r=>r.attempts);
 const save=()=>{if(!data.denied)conv().draft=$('#draft').value;localStorage.setItem(store,JSON.stringify({state:data.id,session:active,data}))};
 const persist=()=>{render();save();return getData()};
 function normalize(){for(const c of all())for(const r of c.requests)for(const a of r.attempts){a.terminalPresentationApplied=a.status!=='running';if(a.status!=='success')delete a.duration;a.completeness=a.empty?'unknown':'complete';a.skillExpanded={};a.steps.forEach((s,i)=>{s.id=s.id||a.id+'-step-'+i;if(s.skill){s.skill.invocationId=s.skill.invocationId||a.id+'-call-'+i;a.skillExpanded[s.skill.invocationId]=!!a.skillOpen}});if(a.loading||a.loadError||a.empty)a.expanded=true;if(a.status==='success'&&!r.resultAttemptId)r.resultAttemptId=a.id;}}
 const chevron='<svg class="process-chevron" viewBox="0 0 24 24" fill="none" stroke="currentColor"><path d="m6 9 6 6 6-6"/></svg>';
 function list(){active=conv().id;$('#sessionList').innerHTML=all().map(c=>{const running=c.requests.some(r=>r.attempts.some(a=>a.status==='running'));return `<button class="session-row ${c.id===active?'active':''}" data-session="${esc(c.id)}" role="option" aria-selected="${c.id===active}" title="${esc(c.title)}"><strong>${esc(c.title)}</strong><span class="session-status" aria-label="${running?'处理中':'会话可查看'}">${running?'◷':'✓'}</span></button>`}).join('');$('#chatTitle').textContent=conv().title;document.querySelectorAll('[data-session]').forEach(b=>b.onclick=()=>{save();active=b.dataset.session;persist()})}
 function skill(s,a){const x=s.skill;if(!x)return '';const key=x.invocationId,opened=!!a.skillExpanded[key];return `<button class="skill-trigger" data-skill="${esc(key)}" data-attempt="${a.id}" aria-expanded="${opened}">调用技能：${esc(x.name)}${chevron}</button><div class="skill-detail" ${opened?'':'hidden'}><strong>${esc(x.name)}</strong><br>调用时名称：${esc(x.name)}${x.version?` · 调用时版本：${esc(x.version)}`:''}${x.started?`<br>开始时间：${esc(x.started)}`:''} · 状态：${esc(x.status)}${x.duration?` · 耗时：${esc(x.duration)}`:''}${x.result?`<br>结果：${esc(x.result)}`:''}</div>`}
 function card(a,r){const calls=a.steps.filter(s=>s.skill).length;let body='';if(a.loading)body='<div class="loading-process">正在加载处理记录…</div>';else if(a.loadError)body=`<div class="loading-process">处理记录加载失败，最终输出不受影响<br><button class="link retry-load" data-reload="${a.id}">重新加载记录</button></div>`;else if(a.empty)body='<div class="empty-process">该次处理暂无历史过程记录</div>';else{body=a.steps.map(s=>`<div class="step ${s.status}"><div class="step-line"><strong>${esc(s.title)}</strong><span class="step-time">${esc(s.time)}</span></div><div class="step-result">${esc(s.summary)}</div>${skill(s,a)}</div>`).join('')||'<div class="empty-process">任务已开始，等待处理记录</div>';if(!calls)body+=`<div class="step-result">${a.completeness==='complete'&&a.status==='success'?'本次未调用技能':'技能调用信息暂不可用'}</div>`;if(a.status==='failed')body+='<div class="failure-hint">技能执行未完成，请重新尝试。</div>';}
 const stats=a.empty?'历史过程不可用':a.loading?'正在读取历史记录':a.loadError?'历史记录读取失败':[a.duration?'耗时 '+esc(a.duration):'',a.steps.length?a.steps.length+' 个步骤':'',calls?'技能调用 '+calls+' 次':''].filter(Boolean).join(' · ');
 return `<section class="process-card"><button class="process-head" data-toggle="${a.id}" aria-expanded="${a.expanded}" aria-controls="body-${a.id}" aria-label="${a.expanded?'收起':'展开'}处理记录"><span><span class="status ${a.status}">${r.attempts.length>1?'第 '+a.number+' 次 · ':''}${a.stopping?'正在停止':names[a.status]}</span><span class="process-meta">${stats}</span></span>${chevron}</button><div class="process-body" id="body-${a.id}" ${a.expanded?'':'hidden'}>${body}</div>${(a.status==='failed'||a.status==='cancelled')&&r.attempts.at(-1)===a?`<div class="attempt-actions"><button data-retry="${r.id}" ${attempts().some(x=>x.status==='running')?'disabled':''}>重新尝试</button></div>`:''}${a.status==='running'?`<div class="attempt-actions"><button data-stop="${a.id}" ${a.stopping?'disabled':''}>${a.stopping?'正在停止…':'停止处理'}</button></div>`:''}</section>`;
 }
 function ready(r){return r.result&&r.attempts.some(a=>a.id===r.resultAttemptId&&a.status==='success')}
 function request(r){return `<article class="message user"><div class="message-label">你</div><div class="bubble">${esc(r.title)}</div></article><article class="message assistant"><div class="message-label">内容协作智能体</div>${r.attempts.map(a=>card(a,r)).join('')}${ready(r)?`<div class="assistant-reply">${esc(r.result)}</div>`:''}</article>`}
 function canvas(){const c=conv(),r=[...c.requests].reverse().find(ready),title=c.id==='s2'?'试用期培训计划':'新人培训课程大纲';$('#canvasTitle').textContent=r?title:'暂无生成内容';$('#resultMeta').textContent=r?'所属会话：'+c.title:'当前会话尚未生成成果';$('#canvas').innerHTML=r?`<h1>${title}</h1><p class="canvas-lead">${esc(r.result)}</p><h2>课程目标</h2><p>${c.id==='s2'?'完成试用期学习与阶段实践，熟悉岗位职责和协作规范。':'建立对业务、协作流程和常用工具的基础认识，能够在培训后完成日常协作任务。'}</p><h2>课程结构</h2><p>${c.id==='s2'?'入职学习；岗位实践；阶段反馈与复盘。':'第一节认识团队与业务；第二节'+(r.id==='r3'?'案例练习':'协作规范')+'；第三节常用流程与工具；第四节学习小结。'}</p>`:'<div class="empty-process">生成完成后，内容将在此展示</div>';$('.asset-list').innerHTML=`<header class="asset-head"><span>生成内容</span><span class="muted">${r?1:0}</span></header>${r?`<div class="asset-item active"><div><strong>${title}</strong><small>文档 · 已生成</small></div></div>`:'<div class="empty-process">暂无成果</div>'}<footer class="asset-foot">${esc(c.title)}</footer>`;}
 function events(){document.querySelectorAll('[data-toggle]').forEach(b=>b.onclick=()=>{const a=attempts().find(a=>a.id===b.dataset.toggle);a.expanded=!a.expanded;persist()});document.querySelectorAll('[data-skill]').forEach(b=>b.onclick=()=>{const a=attempts().find(a=>a.id===b.dataset.attempt);a.skillExpanded[b.dataset.skill]=!a.skillExpanded[b.dataset.skill];persist()});document.querySelectorAll('[data-reload]').forEach(b=>b.onclick=()=>{const a=attempts().find(a=>a.id===b.dataset.reload);a.loadError=false;a.loading=true;persist()});document.querySelectorAll('[data-retry]').forEach(b=>b.onclick=()=>retry(b.dataset.retry));document.querySelectorAll('[data-stop]').forEach(b=>b.onclick=()=>cancel(b.dataset.stop));}
 function render(){const scroll=$('#messages').scrollTop;document.body.dataset.state=data.id;$('.composer').hidden=!!data.denied;$('.results').hidden=!!data.denied;$('.asset-list').hidden=!!data.denied;if(data.denied){$('#sessionList').innerHTML='<button class="session-row" id="accessBack"><strong>返回可访问会话</strong></button>';$('#chatTitle').textContent='内容协作智能体';$('#messages').innerHTML='<div class="access-denied">暂无权限查看此会话</div>';$('#canvas').replaceChildren();$('#canvasTitle').textContent='';$('#resultMeta').textContent='';$('.asset-list').replaceChildren();$('#draft').value='';$('#accessBack').onclick=()=>loadState('TR03')}else{list();$('#draft').value=conv().draft||'';$('#messages').innerHTML=conv().requests.map(request).join('')||'<div class="empty-process">输入制作要求，开始新的内容协作</div>';canvas();events();$('#messages').scrollTop=scroll;}window.TRReady=true;if(window.parent!==window)window.parent.postMessage({type:'tr-state',state:data.id},location.origin)}
 function loadState(id){data=copy(window.TRStateData[id]||window.TRStateData.TR03);active='s1';normalize();return persist()}
 function running(){return attempts().find(a=>a.status==='running')}
 function finish(a,status){if(a.status!=='running')return;a.status=status;a.stopping=false;a.steps.forEach(s=>{if(s.status==='running'){s.status=status;s.summary=status==='success'?'已完成本步骤':status==='failed'?'技能执行未完成':'已停止';if(s.skill){s.skill.status=status==='success'?'成功':status==='failed'?'失败':'已取消';s.skill.result=status==='success'?'已形成课程结构':'未返回可用结果';delete s.skill.duration;}}});if(!a.terminalPresentationApplied){a.expanded=status!=='success';a.terminalPresentationApplied=true}a.completeness='complete';}
 function advance(){if(data.denied)return getData();const loading=attempts().find(a=>a.loading);if(loading){loading.loading=false;loading.loadError=false;return persist()}const a=running();if(!a)return getData();if(a.stopping){finish(a,'cancelled');return persist()}a.progress=(a.progress??0)+1;if(a.progress===0){a.steps.push({id:a.id+'-read',title:'读取培训资料',status:'success',summary:'已读取可用培训资料'},{id:a.id+'-skill',title:'调用课程大纲整理技能',status:'running',summary:'正在整理课程结构',skill:{invocationId:a.id+'-call',name:'课程大纲整理',version:'1.2',status:'运行中',result:'等待结果'}});}else if(a.progress===1){a.steps.forEach(s=>{if(s.status==='running'){s.status='success';s.summary='已生成课程结构';if(s.skill){s.skill.status='成功';s.skill.result='已形成课程结构';}}});a.steps.push({id:a.id+'-output',title:'整理最终输出',status:'running',summary:'正在整理可编辑文档'});a.completeness='unknown';}else{finish(a,'success');const r=conv().requests.find(r=>r.attempts.includes(a));r.result='已完成'+(conv().id==='s2'?'试用期培训计划':'新人培训课程大纲')+'，已同步至右侧内容画布。';r.resultAttemptId=a.id;}return persist()}
 function fail(){if(!data.denied){const a=running();if(a)finish(a,'failed')}return persist()}
 function cancel(id){if(!data.denied){const a=id?attempts().find(a=>a.id===id):running();if(a&&a.status==='running')a.stopping=true}return persist()}
 function fresh(number,retryOf){const id='attempt-'+Date.now()+'-'+(++sequence);return {id,number,status:'running',progress:-1,expanded:true,terminalPresentationApplied:false,completeness:'unknown',steps:[],skillExpanded:{},retryOfAttemptId:retryOf}}
 function retry(id){if(data.denied||running())return;const r=conv().requests.find(r=>r.id===id),previous=r?.attempts.at(-1);if(previous&&!['failed','cancelled'].includes(previous.status))return;r.attempts.push(fresh(r.attempts.length+1,previous.id));return persist()}
 function getData(){return copy(data)}
 $('#draft').addEventListener('input',save);$('#draft').addEventListener('keydown',e=>{if(e.key==='Enter'&&!e.shiftKey&&!e.isComposing){e.preventDefault();const title=e.currentTarget.value.trim();if(!title||data.denied||running())return;conv().requests.push({id:'request-'+Date.now(),title,attempts:[fresh(1)],result:''});conv().draft='';$('#draft').value='';persist();$('#draft').focus()}});
 $('#newSession').onclick=()=>{if(!data.denied)save();if(data.denied){data={id:'TR03',conversations:[]};}const c={id:'session-'+Date.now(),title:'新会话',draft:'',requests:[]};all().push(c);active=c.id;persist();$('#draft').focus()};$('.collapse-nav').setAttribute('aria-expanded',String(innerWidth>1500));$('.collapse-nav').onclick=()=>{const expanded=$('.collapse-nav').getAttribute('aria-expanded')!=='true';document.body.classList.toggle('nav-expanded',expanded);document.body.classList.toggle('collapsed',!expanded);$('.collapse-nav').setAttribute('aria-expanded',String(expanded));$('.collapse-nav').setAttribute('aria-label',expanded?'收缩导航':'展开导航')};document.querySelectorAll('.sidebar a').forEach(a=>{a.title=a.textContent.trim();a.setAttribute('aria-label',a.title)});$('#modelSelect').disabled=true;$('#modelSelect').title='本原型暂不演示模型切换';
 window.addEventListener('message',e=>{if(e.origin!==location.origin)return;const x=e.data||{};if(x.type==='tr-demo-action'){if(x.action==='advance')advance();else if(x.action==='fail')fail();else if(x.action==='cancel')cancel();else if(x.action==='loadState')loadState(x.state)}});
 let p={};try{p=JSON.parse(localStorage.getItem(store)||'{}')}catch{}const fixed=new URLSearchParams(location.search).get('state');const reloading=performance.getEntriesByType('navigation')[0]?.type==='reload';if(p.data&&(!fixed||reloading)){data=p.data;active=p.session||'s1';if(reloading&&!data.denied)all().forEach(c=>c.requests.forEach(r=>r.attempts.forEach(a=>{if(a.status==='success')a.expanded=false})));render()}else if(fixed){loadState(fixed)}else loadState('TR03');window.TRDemo={states:Object.keys(window.TRStateData).map(id=>({id,title:id})),loadState,advance,fail,cancel,getData};
})();

